import type { Request, Response } from "express";
import { issueService } from "./issue.service";
import sendResponse from "../../utils/sendResponse";
import { StatusCodes } from "http-status-codes";

// Create Issue
const createIssue = async (req: Request, res: Response) => {
    try {
        const user = req.user as { 
            id: number;
        }
        const result = await issueService.createIssueIntoDB(req.body, user.id);

        return sendResponse(res, StatusCodes.CREATED, {
            success: true,
            message: "Issue Created Successfully!",
            data: result.rows[0],
        })
    } catch (error: any) {
        return sendResponse(res, StatusCodes.INTERNAL_SERVER_ERROR, {
            success: false,
            message: error.message,
        })
    }
}

// Get Single Issue
const getSingleIssue = async (req: Request, res: Response) => {
    const { id } = req.params
    try {
       const result = await issueService.getSingleIssueFromDB(id as string) 

       return sendResponse(res, StatusCodes.OK, {
        success: true,
        message: "Issue retrieved successfully!",
        data: result,
       })
    } catch (error : any) {
        return sendResponse(res, StatusCodes.INTERNAL_SERVER_ERROR, {
            success: false,
            message: error.message,
        })
    }
}

// Get All Issues
const GetAllIssues = async (req: Request, res: Response) => {
    try {
        const { sort, type, status } = req.query;

        const result = await issueService.getAllIssuesFromDB(sort as string, type as string, status as string)

        return sendResponse(res, StatusCodes.OK, {
            success: true,
            message: "Issues retrieved Successfully!!",
            data: result,
        })
    } catch (error : any) {
        return sendResponse(res, StatusCodes.INTERNAL_SERVER_ERROR, {
            success: false,
            message: error.message,
        })
    }


}

// Update Issue
const updateIssue = async (req: Request, res: Response) => {
    const { id } = req.params;
    const user = req.user as {
        id: string;
        name: string;
        role: 'contributor' | 'maintainer';
    }
    try {
       const result = await issueService.updateIssueIntoDB(id as string, req.body, user)

       return sendResponse(res, StatusCodes.OK, {
        success: true,
        message: "Issue Updated Successfully",
        data: result,
       })
        
    } catch (error : any) {
        return sendResponse(res, StatusCodes.INTERNAL_SERVER_ERROR, {
            success: false,
            message: error.message,
        })
    }
}

// Delete Issue
const deleteIssue = async (req: Request, res: Response) => {
    const { id } = req.params;
    try {
       const result = await issueService.deleteIssueFromDB(id as string);
       
       if (result.rowCount === 0) {
        return sendResponse(res, StatusCodes.NOT_FOUND, {
            success: false,
            message: "User Not found!",
        })
    }

        return sendResponse(res, StatusCodes.OK, {
            success: true,
            message: "Issue Deleted Successfully!!!"
         })

    } catch (error : any) {
        return sendResponse(res, StatusCodes.INTERNAL_SERVER_ERROR, {
            success: false,
            message: error.message,
        })
    }
}

export const issueController = {
    createIssue,
    getSingleIssue,
    GetAllIssues,
    updateIssue,
    deleteIssue
}